#!/usr/bin/env python3
"""Inject default channels into the MeshCore companion firmware before compiling.

Reads requested_config.json ({"channels":[{"name","psk"},...]}), validates it,
writes examples/companion_radio/default_channels.h and patches MyMesh.cpp and
DataStore.{h,cpp} so the channels are added on the FIRST boot only (when no
saved channel file exists). PSK values are never printed.
"""
import base64
import binascii
import json
import re
import sys

COMPANION = "examples/companion_radio"
MAX_EXTRA = 30
# Meshtastic default key; "AQ==" (1 byte, n) means this key with last byte += n-1.
MT_DEFAULT_PSK = bytes.fromhex("d4f1bb3a20290759f0bcffabcf4e6901")
NAME_RE = re.compile(r'^[ -~]{1,31}$')  # printable ASCII, max 31 chars


def fail(msg):
    print(f"::error::{msg}")
    sys.exit(1)


def normalize_psk(raw: str) -> str:
    raw = raw.strip()
    if re.fullmatch(r"[0-9a-fA-F]{32}|[0-9a-fA-F]{64}", raw):
        key = bytes.fromhex(raw)
    else:
        try:
            key = base64.b64decode(raw + "=" * (-len(raw) % 4), validate=True)
        except (binascii.Error, ValueError):
            fail("PSK no valida (base64 o hex)")
        if len(key) == 1 and 1 <= key[0] <= 10:  # Meshtastic shorthand
            k = bytearray(MT_DEFAULT_PSK)
            k[-1] = (k[-1] + key[0] - 1) & 0xFF
            key = bytes(k)
    if len(key) not in (16, 32):
        fail("PSK debe ser de 16 o 32 bytes (o AQ== de Meshtastic)")
    return base64.b64encode(key).decode()


def patch(path, old, new):
    with open(path, encoding="utf-8") as f:
        text = f.read()
    if text.count(old) != 1:
        fail(f"parche no aplicable en {path}: el codigo de MeshCore ha cambiado")
    with open(path, "w", encoding="utf-8") as f:
        f.write(text.replace(old, new))


def main():
    cfg = json.load(open(sys.argv[1], encoding="utf-8"))
    chans = cfg.get("channels") or []
    if not isinstance(chans, list) or len(chans) > MAX_EXTRA:
        fail(f"maximo {MAX_EXTRA} canales extra")
    seen, rows = set(), []
    for ch in chans:
        name = str(ch.get("name", ""))
        if not NAME_RE.match(name) or '"' in name or "\\" in name:
            fail("nombre de canal no valido (ASCII, 1-31 caracteres, sin comillas ni barra)")
        psk = normalize_psk(str(ch.get("psk", "")))
        if psk in seen:
            continue  # same key = same channel
        seen.add(psk)
        rows.append((name, psk))

    body = ",\n".join(f'  {{"{n}", "{p}"}}' for n, p in rows)
    header = (
        "// Generated by apply_default_channels.py - do not edit.\n#pragma once\n"
        f"#define DEFAULT_CHANNELS_COUNT {len(rows)}\n"
        "static const char* const DEFAULT_CHANNELS[][2] = {\n"
        f"{body}{',' if rows else ''}\n  {{nullptr, nullptr}}\n}};\n"
    )
    open(f"{COMPANION}/default_channels.h", "w", encoding="utf-8").write(header)

    my = f"{COMPANION}/MyMesh.cpp"
    patch(my, '#define PUBLIC_GROUP_PSK                "izOH6cXN6mrJ5e26oRXNcg=="',
          '#include "default_channels.h"\n#define PUBLIC_GROUP_PSK                "izOH6cXN6mrJ5e26oRXNcg=="')
    patch(my, '  addChannel("Public", PUBLIC_GROUP_PSK); // pre-configure public channel\n',
          '  addChannel("Public", PUBLIC_GROUP_PSK); // pre-configure public channel\n'
          '  if (DEFAULT_CHANNELS_COUNT > 0 && !_store->hasSavedChannels()) {  // first boot only\n'
          '    for (int i = 0; i < DEFAULT_CHANNELS_COUNT; i++) addChannel(DEFAULT_CHANNELS[i][0], DEFAULT_CHANNELS[i][1]);\n'
          '  }\n')
    patch(f"{COMPANION}/DataStore.h", "  void loadChannels(DataStoreHost* host);\n",
          "  void loadChannels(DataStoreHost* host);\n  bool hasSavedChannels();\n")
    patch(f"{COMPANION}/DataStore.cpp", "void DataStore::saveChannels(DataStoreHost* host) {",
          'bool DataStore::hasSavedChannels() {\n    File file = openRead(_getContactsChannelsFS(), "/channels2");\n'
          "    if (file) { file.close(); return true; }\n    return false;\n}\n\n"
          "void DataStore::saveChannels(DataStoreHost* host) {")
    print(f"Canales por defecto inyectados: {len(rows)}")


if __name__ == "__main__":
    main()
